```csharp
public sealed record BlogViews(int BlogId, int TotalViews);

public static async Task<List<BlogViews>> GetViewsByBlogAsync(
    BlogContext context,
    string searchTerm,
    CancellationToken cancellationToken)
{
    var query =
        from post in context.Posts
        where post.Title.Contains(searchTerm)
        group post by post.BlogId
        into blogPosts
        select new BlogViews(
            blogPosts.Key,
            blogPosts.Sum(post => post.Views));

    return await query.ToListAsync(cancellationToken);
}
```

```csharp
public static async Task<Dictionary<int, int>> GetTotalViewsPerBlogAsync(
    BlogContext context,
    string searchTerm,
    CancellationToken cancellationToken)
{
    var query =
        from post in context.Posts
        where post.Title.Contains(searchTerm)
        group post by post.BlogId into blogPosts
        select new
        {
            BlogId = blogPosts.Key,
            TotalViews = blogPosts.Sum(post => post.Views)
        };

    var totals = await query.ToListAsync(cancellationToken);

    return totals.ToDictionary(item => item.BlogId, item => item.TotalViews);
}
```

